"use client";

import { motion } from "motion/react";

export function AuroraHeadlineTailwind({ text = "Restrained spectral illumination" }) {
  return (
    <h1 className="flex flex-wrap text-2xl font-semibold tracking-tight">
      {text.split(" ").map((w, i) => (
        <span key={i} className="mr-2 overflow-hidden pb-1">
          <motion.span
            initial={{ y: "100%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ duration: 0.55, delay: i * 0.06 }}
            className="inline-block bg-gradient-to-r from-zinc-100 via-sky-200 to-indigo-200 bg-clip-text text-transparent"
          >
            {w}
          </motion.span>
        </span>
      ))}
    </h1>
  );
}
